// src/preferences/parse-preference-change.ts
export type PreferenceChange = { key: 'email_updates' | 'product_tips'; enabled: boolean };

export function parsePreferenceChange(input: unknown): PreferenceChange {
  if (!input || typeof input !== 'object') throw new InvalidPreference(input);
  const { key, enabled } = input as Record<string, unknown>;
  if ((key !== 'email_updates' && key !== 'product_tips') || typeof enabled !== 'boolean') {
    throw new InvalidPreference(input);
  }
  return { key, enabled };
}
