// src/events/parse-event-line.ts
export function parseEventLine(text: string, lineNumber: number): ImportedEvent {
  let value: unknown;
  try { value = JSON.parse(text); } catch (cause) { throw new InvalidEventLine(lineNumber, { cause }); }
  if (!isImportedEvent(value)) throw new InvalidEventLine(lineNumber);
  return value;
}
